  db.exec(`CREATE TABLE accounts (id INTEGER PRIMARY KEY, cents INTEGER NOT NULL);`);
  const stmt = db.prepare('INSERT INTO accounts VALUES (?, ?)');
  stmt.run(1, 5000);
  stmt.run(2, 1000);
  try {
    return run(db);
  } finally {
    db.close();
  }
}

