}

export function pageKeyset(db, limit, afterId) {
  return db
    .prepare('SELECT id, title FROM posts WHERE id > ? ORDER BY id LIMIT ?')
    .all(afterId, limit);
}

// ──────────────────────────── tests ──────────────────────────────────────

